import java.util.*;
import java.io.*;

public class Main {
    static int[] bestGoodSubarray(long[] nums, long k) {
        // Write your solution here
        // Return {i, j}, or {-1} if there is no good subarray.
        return new int[]{-1};
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        long k = (long) in.nval;
        long[] nums = new long[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            nums[i] = (long) in.nval;
        }
        int[] res = bestGoodSubarray(nums, k);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < res.length; i++) sb.append(res[i]).append(i + 1 < res.length ? " " : "\n");
        System.out.print(sb);
    }
}
